-- Approximate market boundary outlines, for the admin map.
--
-- 'boundary' is a GeoJSON Polygon (lng/lat, WGS84) rendered as a translucent
-- outline on /admin/map. 'boundary_source' records how it was derived:
--   'osm'         — an OpenStreetMap administrative boundary for the closest
--                   matching named place, ACCEPTED only when its bounding-box
--                   diagonal is <= 12 km (rejects whole-Town-scale matches
--                   that would badly overstate the market's real extent).
--   'field-data'  — no suitable OSM feature exists (or it was rejected above),
--                   so the outline is the convex hull of that market's own
--                   surveys' GPS points instead (a hexagon around the single
--                   point when there are 1-2 surveys). This is real field
--                   data, but only as complete as current survey coverage —
--                   it will look sparse for a market with few visits so far.
-- Neither kind is an authoritative administrative or commercial boundary;
-- both are drawn as visibly approximate. A market added later by an admin
-- has boundary = null and is skipped by the outline layer (marker only).
--
-- Snapshot taken 2026-09-24 from nominatim.openstreetmap.org (ODbL-licensed,
-- (c) OpenStreetMap contributors) and from surveys.gps_lat/gps_lng as of that
-- date. Re-runnable: the two ALTERs are guarded, and every UPDATE is
-- unconditional so a re-run just re-applies the same snapshot.

alter table public.markets add column if not exists boundary jsonb;
alter table public.markets add column if not exists boundary_source text
  check (boundary_source is null or boundary_source in ('osm', 'field-data'));

update public.markets set boundary = '{"type":"Polygon","coordinates":[[[67.01757149302445,24.8631386],[67.01608209651222,24.865479209199417],[67.01310330348777,24.865479209199417],[67.01161390697554,24.8631386],[67.01310330348777,24.86079799080058],[67.01608209651222,24.86079799080058],[67.01757149302445,24.8631386]]]}'::jsonb, boundary_source = 'field-data' where name = 'Arambagh';
